window.DIGEST.foryou.push(...[{"id": "2112984664256241837", "url": "https://x.com/claudeai/status/2112984664256241837", "text": "We’re opening a research preview of Claude Duet, a new app where Claude works as a proactive agent.\n\nIt comes to you with what needs your attention, completes tasks you ask of it, keeps working when you step away, and checks with you before it acts on your behalf.", "name": "Claude", "handle": "claudeai", "avatar": "https://pbs.twimg.com/profile_images/1950950107937185792/QOfEjFoJ_200x200.jpg", "likes": 43210, "rts": 3270, "replies": 1714, "views": 5528053, "ts": 1792609775, "media": [{"type": "video", "url": "https://video.twimg.com/amplify_video/2112982862186106880/vid/avc1/640x360/L7zosiEUW76tqYr-.mp4?tag=29", "hd": "https://video.twimg.com/amplify_video/2112982862186106880/vid/avc1/640x360/L7zosiEUW76tqYr-.mp4?tag=29", "thumb": "https://pbs.twimg.com/media/HVLUnMDWsAAn7Pw.png", "dur": 100}], "quote": null, "reply_to": null, "cat": "AI Models & Labs", "score": 8.24, "thread": [], "tier": "must"}, {"id": "2112803615089783081", "url": "https://x.com/proverbs_14_23/status/2112803615089783081", "text": "Important to remember that in 1940, most of Hitler’s advisors argued against an invasion of France. On paper, the French were stronger in key areas. A few of his staff even threatened to resign.\n\nHe made the call to invade entirely because he thought they were faggots.\n\nAnd he was right.", "name": "Richard “Beebo” Russell", "handle": "proverbs_14_23", "avatar": "https://pbs.twimg.com/profile_images/2017698204288946176/uDDZOgYZ_200x200.jpg", "likes": 38509, "rts": 2039, "replies": 282, "views": 1204041, "ts": 1792566610, "media": [], "quote": {"id": "2112256851937231275", "url": "https://x.com/Dominicano1621/status/2112256851937231275", "text": "Vive la France 🇫🇷🫠", "name": "Dominicano1621", "handle": "Dominicano1621", "avatar": "https://pbs.twimg.com/profile_images/2076322247111856128/aMMN78on_200x200.jpg", "likes": 38426, "rts": 2980, "replies": 1998, "views": 11112914, "ts": 1792436251, "media": [{"type": "video", "url": "https://video.twimg.com/amplify_video/2112256817862459392/vid/avc1/480x852/shUvBS8kSev4Sido.mp4?tag=29", "hd": "https://video.twimg.com/amplify_video/2112256817862459392/vid/avc1/720x1280/6uP46hgOPJJmuwkV.mp4?tag=29", "thumb": "https://pbs.twimg.com/amplify_video_thumb/2112256817862459392/img/EM956JFBbqC9PL4_.jpg", "dur": 14}], "quote": null, "reply_to": null}, "reply_to": null, "cat": "Research & Safety", "score": 7.89, "thread": [], "tier": "must"}, {"id": "2112819774573179175", "url": "https://x.com/UnitreeRobotics/status/2112819774573179175", "text": "Unitree Introducing: H2-X Kung Fu Legend Guardian🤖\nPowerful performance to serve and guard you, with a maximum endurance of approximately 8 hours.\nPlease use the robot safely and in a friendly manner.", "name": "Unitree", "handle": "UnitreeRobotics", "avatar": "https://pbs.twimg.com/profile_images/1844926705389142016/nIEbH8rV_200x200.jpg", "likes": 20513, "rts": 2766, "replies": 1427, "views": 4244752, "ts": 1792570463, "media": [{"type": "video", "url": "https://video.twimg.com/amplify_video/2112814220194828288/vid/avc1/1280x720/qQFeTMrcQITPE76L.mp4?tag=29", "hd": "https://video.twimg.com/amplify_video/2112814220194828288/vid/avc1/1920x1080/dphHVlNFst1G9RW0.mp4?tag=29", "thumb": "https://pbs.twimg.com/amplify_video_thumb/2112814220194828288/img/RL8lXu0dfq4qop9M.jpg", "dur": 61}], "quote": null, "reply_to": null, "cat": "AI Tools & Agents", "score": 7.76, "thread": [], "tier": "must"}, {"id": "2112966832969708020", "url": "https://x.com/elonmusk/status/2112966832969708020", "text": "Grok @Bot can help protect and fix your credit rating. Just ask it to do so!", "name": "Elon Musk", "handle": "elonmusk", "avatar": "https://pbs.twimg.com/profile_images/2103567689515954176/aR-Kjpp4_200x200.jpg", "likes": 9932, "rts": 1089, "replies": 1236, "views": 7794774, "ts": 1792605524, "media": [], "quote": {"id": "2112963173666185655", "url": "https://x.com/BrianRoemmele/status/2112963173666185655", "text": "I had a friend run this Grok Bot I built for them a few weeks ago and guess what?\n\n7 entires from a scammer that took over his credit.\n\n$65,000+ of defaulted credit!\n\nGrok Bot is fixing this.\n\nGet it: https://x.ai/bot/vY1eft-dZTKssiaUQvJEc you will not be disappointed!", "name": "Brian Roemmele", "handle": "BrianRoemmele", "avatar": "https://pbs.twimg.com/profile_images/1492616506/Brian-Med-Green-Fin_200x200.png", "likes": 587, "rts": 77, "replies": 57, "views": 7417739, "ts": 1792604652, "media": [{"type": "photo", "url": "https://pbs.twimg.com/media/HVLAzryacAA5EDx.jpg?name=orig"}], "quote": null, "reply_to": null}, "reply_to": null, "cat": "AI Models & Labs", "score": 7.65, "thread": [], "tier": "must"}, {"id": "2112872778265477478", "url": "https://x.com/MarioNawfal/status/2112872778265477478", "text": "🇫🇷 Macron on France's riots:\n\n\"There has been foreign manipulation of information afterward\n\nThis led to unacceptable and downright stupid comments from many people, including foreign leaders.\n\nPeople have claimed that we were invaded by hordes of migrants and Islamists, which is completely false.\"\n\nApparently, France's problems can all be explained by AI-generated images and foreign interference. \n\nThey talk to us like we're idiots...\n\nWriter: Samuel https://x.com/clashreport/status/2112853606776869335/video/1", "name": "Mario Nawfal", "handle": "MarioNawfal", "avatar": "https://pbs.twimg.com/profile_images/1938244629071015936/UwtzYY-R_200x200.jpg", "likes": 8499, "rts": 1836, "replies": 2086, "views": 536657, "ts": 1792583100, "media": [{"type": "video", "url": "https://video.twimg.com/amplify_video/2112853340639961088/vid/avc1/1280x720/FdjZ6DzDEZRkX_yI.mp4?tag=29", "hd": "https://video.twimg.com/amplify_video/2112853340639961088/vid/avc1/1920x1080/1klr3rxF9TgaIX0b.mp4?tag=29", "thumb": "https://pbs.twimg.com/amplify_video_thumb/2112853340639961088/img/dq63IeKCBFAGpzPJ.jpg", "dur": 32}], "quote": null, "reply_to": null, "cat": "AI Video, Art & Music", "score": 7.59, "thread": [], "tier": "must"}, {"id": "2112945805686604033", "url": "https://x.com/OpenAI/status/2112945805686604033", "text": "If you are wondering whether your website is affected, we have packaged a Codex skill to help check.\n\nPoint your Codex at this repo to guide you through it: https://github.com/openai/php2shell-checker", "name": "OpenAI", "handle": "OpenAI", "avatar": "https://pbs.twimg.com/profile_images/1885410181409820672/ztsaR0JW_200x200.jpg", "likes": 8239, "rts": 1059, "replies": 288, "views": 1064036, "ts": 1792600511, "media": [], "quote": {"id": "2112907856018309586", "url": "https://x.com/OpenAI/status/2112907856018309586", "text": "OpenAI models helped researchers—operating as part of our Patch the Planet initiative—discover critical security flaws in PHP, an open-source programming language used to run an estimated 70% of websites.\n\nOver the past two months, we led a coalition of maintainers, researchers, and security providers to prepare fixes and protections ahead of disclosure. This duration was necessary because the fix was quite intricate and required a major change to the PHP engine. Every site using PHP can now safely upgrade their version to stay secure, in addition to applying mitigations from various security vendors.\n\nDue to the severity of these flaws and PHP’s widespread use, we consider this bug to be one of the most impactful vulnerabilities in recent memory. It also marks a new phase, where AI can find security bugs with internet-scale impact. \n\nThis is an example of the Defender’s Window in action: to our knowledge, frontier AI was able to find this vulnerability ahead of attackers, giving defenders time to prepare.\nhttps://openai.com/index/coordinated-disclosure-of-critical-vulnerabilities/", "name": "OpenAI", "handle": "OpenAI", "avatar": "https://pbs.twimg.com/profile_images/1885410181409820672/ztsaR0JW_200x200.jpg", "likes": 13815, "rts": 2762, "replies": 541, "views": 5062111, "ts": 1792591463, "media": [], "quote": null, "reply_to": null}, "reply_to": null, "cat": "AI Models & Labs", "score": 7.51, "thread": [], "tier": "must"}, {"id": "2113113711644737835", "url": "https://x.com/AISafetyMemes/status/2113113711644737835", "text": "This is the most serious 48 hours in cybersecurity history.\n\n\"Black October\" they're calling it\n\nIt seems every *hour* there's a new incident, that in a typical year, would be one of the biggest incidents of the *entire year*\n\nSUMMARY OF THE LAST 48 HOURS:\n\nYEAR-LEVEL INCIDENTS (In a typical year, these would be among the biggest incidents of the year):\n\n1. PHP2Shell: a hole in the software behind ~70% of websites. Governments took sites offline.\n2. eMudhra: the master keys that prove websites are real were cracked. One was the number 4.\n3. California: data on every public school student since 2023 stolen, including disability status\n4. Railway: hackers stole customers' secret keys from a hosting platform used by millions of developers\n5. Zeabur: 321,810 accounts breached. The company is shutting down.\n6. LiteLLM: an AI tool downloaded 3.4 million times a day was poisoned with a password stealer\n7. GitLab: a 10-out-of-10 severity hole in every version since 2014\n8. Cairn: criminals used an AI hacking tool to break into 100+ companies\n9. Ahold Delhaize: hackers knocked the owner of Food Lion and Stop & Shop offline\n10. Onamae: malware planted on up to 26,739 customer servers in Japan\n\nMONTH-LEVEL INCIDENTS (In a typical month, these would be among the biggest incidents):\n\n11. Signal: a bug could leave your mic and camera on after you hang up\n12. NGINX: 3 critical holes in software running ~1/3 of websites\n13. HTTP/3: a single connection can crash 7 of the 10 web server types tested\n14. Plex: hackers breaking into home media servers\n15. SafePay ransomware: FBI warns it has hit 600+ critical infrastructure organizations\n16. Palo Alto: ransomware gangs breaking in through company firewalls\n17. Bullhorn: platform used by 10,000+ companies knocked offline\n18. Medi-Cal: 970,000 patients' data stolen\n19. WordPress: hackers stole a plugin maker's keys and used them to plant backdoors on websites\n20. AOMEI: backup software's update server handed out a backdoor\n21. Meta Muse: Meta's AI agent exposed users' personal and business secrets\n22. Tor: 333 relays hijacked to steal logins\n23. TiDB Cloud: database company's cloud breached\n\nAlso serious:\n\n24. State Bank of India: India's biggest bank confirms a data breach\n25. OVHcloud: hackers slipped a password stealer into a cloud company's official tool\n26. Siemens: a software hole being used to spread malware\n27. North Korea: state hackers launch a new attack campaign on South Korea", "name": "AI Notkilleveryoneism Memes ⏸️", "handle": "AISafetyMemes", "avatar": "https://pbs.twimg.com/profile_images/2106622642778468353/KftYoNib_200x200.jpg", "likes": 3451, "rts": 569, "replies": 90, "views": 145657, "ts": 1792640543, "media": [{"type": "photo", "url": "https://pbs.twimg.com/media/HVNI-gNaAAEYBJk.jpg?name=orig"}], "quote": {"id": "2113053339936293055", "url": "https://x.com/4rcherhume/status/2113053339936293055", "text": "Guys I’m scared the takeoff is starting. I swear any one of the ~10 CVEs that dropped in the last 24 hours would’ve been “one of the worst in recent years” except a new one is dropping every hour", "name": "Archer", "handle": "4rcherhume", "avatar": "https://pbs.twimg.com/profile_images/2053340527576170506/cwH6ZGGQ_200x200.jpg", "likes": 1452, "rts": 68, "replies": 21, "views": 172332, "ts": 1792626149, "media": [], "quote": null, "reply_to": null}, "reply_to": null, "cat": "AI Tools & Agents", "score": 7.39, "thread": [], "tier": "must"}, {"id": "2112944385415426249", "url": "https://x.com/RichardSocher/status/2112944385415426249", "text": "Introducing Flint, @Recursive_SI’s first model: a fast local coding model built with our automated research system, the Eureka Machine.\n\n• Best-in-class fast local coding\n• Up to 2x faster than comparable models: 125+ tokens/sec on a MacBook Pro, 150+ on RTX Spark\n• Built from scratch in under 4 months\n\nPrivate, unmetered intelligence on your own machine. Open weights available now on @huggingface, run it locally on your favorite framework or try it for free on @opencode or @pidotdev.", "name": "Richard Socher", "handle": "RichardSocher", "avatar": "https://pbs.twimg.com/profile_images/1232361282759610368/YYxndVmI_200x200.jpg", "likes": 6093, "rts": 643, "replies": 485, "views": 2499045, "ts": 1792600172, "media": [{"type": "video", "url": "https://video.twimg.com/amplify_video/2112941750809419776/vid/avc1/1280x720/ljeVLZeytT--ckEJ.mp4?tag=29", "hd": "https://video.twimg.com/amplify_video/2112941750809419776/vid/avc1/3840x2160/OjycwsU9wNo0PMbi.mp4?tag=29", "thumb": "https://pbs.twimg.com/amplify_video_thumb/2112941750809419776/img/MJaHRrNTo-Kg92Pb.jpg", "dur": 161}], "quote": null, "reply_to": null, "cat": "AI Models & Labs", "score": 7.38, "thread": [], "tier": "must"}, {"id": "2112802425052754183", "url": "https://x.com/AnzalAbidi/status/2112802425052754183", "text": "Crazy 72 hours in security. Three major incidents dropped back-to-back: eMudhra, PingCAP (TiDB Cloud), and PHP.\n\nHere is the short version of what happened and who got hit.\n\n1. eMudhra (Trusted CA compromise)\n\neMudhra generated 8 intermediate CA certificates in April 2025 (cross-signed by Sectigo). A bug in their HSM key-wrapping test script created a second set of P-384 keys where the private keys were single-byte numbers under 256. Operators picked the wrong key labels and signed them into real CA certs.\n\nOne of the intermediate CA private keys was literally the number 4.\nThe other seven: 56, 66, 115, 155, 156, 230, 237.\n\nThree weeks later (May 2025), their CRL signatures started failing because the CRL signer was using the real keys instead of the weak ones. Instead of asking why the keys didn't match, someone switched the CRL signer to the weak keys and closed the ticket.\n\n• Browsers are safe: Chrome, Firefox, Apple, and Microsoft already blocked them, and zero rogue certs hit CT logs.\n• Servers are not: curl, Python (certifi), Go binaries, and Docker base images don't check CRLs. Update ca-certificates, certifi, and Go (1.27.3 / 1.26.10).\n• 10-second check on any server:\n  curl https://dv-g3b-emudhra.we-have-a-problem.com/\n  (TLS error = safe. 200 OK = still vulnerable.)\n\n2. PingCAP / TiDB Cloud (10.6 TB breach)\n\nAttackers found GCP and Azure credentials committed inside PingCAP's own repos. They set up a replication feed of TiDB Cloud's production control plane and exported the entire database every 6 hours for 22 straight days. 88 full exports, zero alerts. 200 GB is already out on torrents.\n\nBeyond the 413 private repos and 20.6M customer SQL queries logged from their web SQL Editor, PingCAP engineers were pasting customer secrets into Jira tickets.\n\nWho is affected in the leaked records:\n\n• Live credentials exposed in support tickets:\n  - Pinterest: AWS keys for their pingcap-logs S3 bucket\n  - CardX / Silverlake (NPCI-linked env): AWS admin key in a backup log with full access to 258 external S3 buckets\n  - DeBank: 38 presigned S3 URLs\n  - An unnamed AI/dev platform: a 314 MB slow-query log attached to a ticket containing 8,027 live customer secrets (an AWS root key, a GitHub admin PAT over 1,701 repos, 7,485 AWS STS tokens, and 192 OpenAI/Anthropic/Gemini keys)\n\n• Tenants with infra metadata, VPC CIDRs, app-server IPs, or contract pricing exposed:\n  - Tech: Atlassian, Databricks, Airbnb, Baidu, LINE, Nylas, Persona, PatSnap\n  - E-comm & Travel: http://Booking.com, Shopee, Flipkart, Mercari, ZOZO, AEON, Delhivery, Klook\n  - Gaming: Capcom, Square Enix, Konami, Bandai Namco, Cygames, Colopl, DMM\n  - Finance: PayPay, SoftBank, SBI, SB Payment Service, Fujitsu, TOPPAN, Bank of China, China Life\n  - Crypto: Bitget (said only public trade logs were on it and they already left), Pionex, DigiPlus, NFTscan, Chainbase\n\n• Developer profiles leaked (from a purchased http://reo.dev table in PingCAP's BigQuery):\n  - 24,900 personal emails + GitHub/LinkedIn profiles of engineers at Tencent (3,327), Huawei (2,726), ByteDance (2,475), AIG (2,140), Mastercard, Flipkart, and bKash.\n\nIf you use TiDB Cloud: rotate your console API keys, DB passwords, and anything you ever pasted into a support ticket.\n\n3. PHP \"PHP2Shell\" (CVE-2026-109618 & CVE-2026-109619)\n\nTwo CVSS 9.2 pre-auth RCEs leaked yesterday ahead of today's 14:00 UTC patch.\n\nPublic writeups trace it to a heap Use-After-Free in PHP's native C multipart/form-data session upload-progress handler (ext/session/session.c).\n\nBecause C-level multipart parsing runs before line 1 of index.php:\n• App auth, Laravel/WordPress middleware, and file_uploads = Off do not stop it.\n• Only PHP 8.2–8.5 get official patches today (59% of PHP servers on Shodan are on EOL <= 8.1).\n• Until you patch php-fpm: lock php_admin_flag[session.upload_progress.enabled] = off and block unexpected multipart requests at Nginx/Apache/Cloudflare.", "name": "Anzal Abidi", "handle": "AnzalAbidi", "avatar": "https://pbs.twimg.com/profile_images/1844000337163616256/gAbJ-2OD_200x200.jpg", "likes": 9214, "rts": 1365, "replies": 99, "views": 855485, "ts": 1792566326, "media": [], "quote": null, "reply_to": null, "cat": "AI Models & Labs", "score": 7.36, "thread": [], "tier": "must"}, {"id": "2112951651715952725", "url": "https://x.com/netflix/status/2112951651715952725", "text": "10 years of MOONLIGHT. \n\nThe Academy Award-winning film, written and directed by Barry Jenkins, is now on Netflix in the US.", "name": "Netflix", "handle": "netflix", "avatar": "https://pbs.twimg.com/profile_images/1996301804053868544/Xrwvbe1q_200x200.jpg", "likes": 4997, "rts": 862, "replies": 44, "views": 700096, "ts": 1792601905, "media": [{"type": "video", "url": "https://video.twimg.com/amplify_video/2112949259771502598/vid/avc1/1280x720/GVQT-kp9PaqArUlF.mp4?tag=29", "hd": "https://video.twimg.com/amplify_video/2112949259771502598/vid/avc1/1920x1080/yNQaBr93kGA6XLU-.mp4?tag=29", "thumb": "https://pbs.twimg.com/amplify_video_thumb/2112949259771502598/img/jcwAv_CUyLuEeNzB.jpg", "dur": 33}], "quote": null, "reply_to": null, "cat": "AI Video, Art & Music", "score": 7.32, "thread": [], "tier": "must"}, {"id": "2112934412967117297", "url": "https://x.com/elonmusk/status/2112934412967117297", "text": "@RampCapitalLLC @bot Do it both conventionally and with Grok @Bot, then compare. \n\nActually, it’s worth showing Grok last year’s tax returns and see if it finds opportunities for improvement. There may be refunds you’re owed.", "name": "Elon Musk", "handle": "elonmusk", "avatar": "https://pbs.twimg.com/profile_images/2103567689515954176/aR-Kjpp4_200x200.jpg", "likes": 5250, "rts": 251, "replies": 332, "views": 1108575, "ts": 1792597795, "media": [], "quote": null, "reply_to": "2112925935850639453", "cat": "AI Models & Labs", "score": 7.24, "thread": [{"id": "2112925935850639453", "url": "https://x.com/RampCapitalLLC/status/2112925935850639453", "text": "Give me one good reason why I shouldn’t have Grok @bot do my taxes next year", "name": "Ramp Capital", "handle": "RampCapitalLLC", "avatar": "https://pbs.twimg.com/profile_images/1536508197770518528/M5sFqRBX_200x200.jpg", "likes": 788, "rts": 17, "replies": 91, "views": 225689, "ts": 1792595774, "media": [], "quote": null, "reply_to": null}], "tier": "must"}, {"id": "2112859032944087284", "url": "https://x.com/XFreeze/status/2112859032944087284", "text": "Elon Musk: Neuralink's Blindsight vision implant is coming soon\n\n\"Even if somebody's completely blind, we can write directly to the visual cortex\"\n\nThe first version will offer low-resolution vision, but the long-term goal goes much further:\n\n\"You would have very high resolution and be able to see multispectral wavelengths. You could see in infrared, ultraviolet, radar. It's like a superpower situation\"\n https://x.com/XFreeze/status/2017220235984617518/video/1", "name": "X Freeze", "handle": "XFreeze", "avatar": "https://pbs.twimg.com/profile_images/1876785200010539008/2_HFJjq9_200x200.jpg", "likes": 4302, "rts": 751, "replies": 388, "views": 353428, "ts": 1792579823, "media": [{"type": "video", "url": "https://video.twimg.com/amplify_video/2017220079214059521/vid/avc1/720x720/b7at1gRHF_SWnZrv.mp4?tag=21", "hd": "https://video.twimg.com/amplify_video/2017220079214059521/vid/avc1/1080x1080/MEduuyIeEgbO_KEW.mp4?tag=21", "thumb": "https://pbs.twimg.com/amplify_video_thumb/2017220079214059521/img/8Ur6F1y7QvE6qmP0.jpg", "dur": 25}], "quote": null, "reply_to": null, "cat": "AI Video, Art & Music", "score": 7.18, "thread": [], "tier": "must"}, {"id": "2113013247209021918", "url": "https://x.com/ClaudeDevs/status/2113013247209021918", "text": "API version 2026-10-21 is now available.\n\nThe Claude API has evolved a lot, but this is our first official version release since 2023. We plan to release versions more often so you can handle breaking changes before a new model requires them. \n\n2023-06-01 is not deprecated.", "name": "ClaudeDevs", "handle": "ClaudeDevs", "avatar": "https://pbs.twimg.com/profile_images/2044472418815893504/xf14RxM8_200x200.png", "likes": 3346, "rts": 87, "replies": 91, "views": 229327, "ts": 1792616590, "media": [], "quote": null, "reply_to": null, "cat": "AI Models & Labs", "score": 7.1, "thread": [], "tier": "must"}, {"id": "2112984666437546104", "url": "https://x.com/claudeai/status/2112984666437546104", "text": "We designed Claude Duet around Claude Opus 5.5, which gives it the judgment to decide what needs you, what can wait, and when to check with you first. It carries over the memory, skills, and connected apps from your Claude account, so there’s little to set up.", "name": "Claude", "handle": "claudeai", "avatar": "https://pbs.twimg.com/profile_images/1950950107937185792/QOfEjFoJ_200x200.jpg", "likes": 3543, "rts": 72, "replies": 52, "views": 705163, "ts": 1792609776, "media": [], "quote": null, "reply_to": "2112984664256241837", "cat": "AI Models & Labs", "score": 7.07, "thread": [{"id": "2112984664256241837", "url": "https://x.com/claudeai/status/2112984664256241837", "text": "We’re opening a research preview of Claude Duet, a new app where Claude works as a proactive agent.\n\nIt comes to you with what needs your attention, completes tasks you ask of it, keeps working when you step away, and checks with you before it acts on your behalf.", "name": "Claude", "handle": "claudeai", "avatar": "https://pbs.twimg.com/profile_images/1950950107937185792/QOfEjFoJ_200x200.jpg", "likes": 43210, "rts": 3270, "replies": 1714, "views": 5528053, "ts": 1792609775, "media": [{"type": "video", "url": "https://video.twimg.com/amplify_video/2112982862186106880/vid/avc1/640x360/L7zosiEUW76tqYr-.mp4?tag=29", "hd": "https://video.twimg.com/amplify_video/2112982862186106880/vid/avc1/640x360/L7zosiEUW76tqYr-.mp4?tag=29", "thumb": "https://pbs.twimg.com/media/HVLUnMDWsAAn7Pw.png", "dur": 100}], "quote": null, "reply_to": null}], "tier": "must"}, {"id": "2112921529650688312", "url": "https://x.com/gdb/status/2112921529650688312", "text": "Over the past two months, we have been leading a coalition to mitigate one of the most severe bugs in open source software found in recent memory, php2shell, found as part of our Patch the Planet initiative. https://x.com/i/article/2112920540138844160", "name": "Greg Brockman", "handle": "gdb", "avatar": "https://pbs.twimg.com/profile_images/1347621377503711233/bHg3ipfD_200x200.jpg", "likes": 3051, "rts": 284, "replies": 144, "views": 296446, "ts": 1792594723, "media": [], "quote": null, "reply_to": null, "cat": "AI Tools & Agents", "score": 7.02, "thread": [], "tier": "must"}, {"id": "2113071762413871367", "url": "https://x.com/FoxNews/status/2113071762413871367", "text": "A protester appears to get punched during President Trump's South Carolina rally, and the president stops his speech to react to the commotion.\n\n\"Who threw that punch?\" Trump asks, pointing toward the crowd before comparing the person who struck the protester to boxing legend Evander Holyfield.\n\n\"You reminded me of Evander 'The Real Deal' Holyfield,\" Trump says, describing how the protester was struck while shouting.\n\nDownload the FOX News app for the latest details on Trump's remarks. https://foxnews.onelink.me/xLDS/z2jymmyl", "name": "Fox News", "handle": "FoxNews", "avatar": "https://pbs.twimg.com/profile_images/2109614018314862592/Pc5TwaVr_200x200.jpg", "likes": 1342, "rts": 221, "replies": 288, "views": 424350, "ts": 1792630541, "media": [{"type": "video", "url": "https://video.twimg.com/amplify_video/2113071656977514497/vid/avc1/720x1280/xTmzk6gIPdV4E8U9.mp4?tag=16", "hd": "https://video.twimg.com/amplify_video/2113071656977514497/vid/avc1/1080x1920/6sy4M_tdBEehV0Q7.mp4?tag=16", "thumb": "https://pbs.twimg.com/media/HVMjkgMWQAAsf8A.jpg", "dur": 121}], "quote": null, "reply_to": null, "cat": "AI Tools & Agents", "score": 7.02, "thread": [], "tier": "must"}, {"id": "2112986311804022900", "url": "https://x.com/TokenGremlin/status/2112986311804022900", "text": "WAIT, WHAT?!\n\nAnthropic just decided to OBLITERATE OpenAI Dots and Grok Bot, dropping Claude Duet powered by the absolute monster that is Opus 5.5.\n\nWe literally go to sleep, wake up, and Anthropic has launched ANOTHER product to crush its competitors.\n\nTHESE GUYS JUST CAN'T STOP WINNING.\n\nWHAT AN ABSOLUTELY LEGENDARY RUN.", "name": "Token Gremlin", "handle": "TokenGremlin", "avatar": "https://pbs.twimg.com/profile_images/2073095799462940672/YKuJiTq7_200x200.jpg", "likes": 2666, "rts": 76, "replies": 165, "views": 491687, "ts": 1792610168, "media": [], "quote": {"id": "2112984664256241837", "url": "https://x.com/claudeai/status/2112984664256241837", "text": "We’re opening a research preview of Claude Duet, a new app where Claude works as a proactive agent.\n\nIt comes to you with what needs your attention, completes tasks you ask of it, keeps working when you step away, and checks with you before it acts on your behalf.", "name": "Claude", "handle": "claudeai", "avatar": "https://pbs.twimg.com/profile_images/1950950107937185792/QOfEjFoJ_200x200.jpg", "likes": 43199, "rts": 3269, "replies": 1713, "views": 5525351, "ts": 1792609775, "media": [{"type": "video", "url": "https://video.twimg.com/amplify_video/2112982862186106880/vid/avc1/640x360/L7zosiEUW76tqYr-.mp4?tag=29", "hd": "https://video.twimg.com/amplify_video/2112982862186106880/vid/avc1/640x360/L7zosiEUW76tqYr-.mp4?tag=29", "thumb": "https://pbs.twimg.com/media/HVLUnMDWsAAn7Pw.png", "dur": 100}], "quote": null, "reply_to": null}, "reply_to": null, "cat": "AI Models & Labs", "score": 6.99, "thread": [], "tier": "must"}, {"id": "2113088596299149410", "url": "https://x.com/FoxNews/status/2113088596299149410", "text": "Rep. Ilhan Omar says she's living \"paycheck to paycheck\" despite previous financial disclosures listing up to $30 million in reported assets.\n\nIn her first public interview since a reported raid on her Washington, D.C., home, the Minnesota Democrat calls her family's finances \"working class,\" pointing to raising four children and driving a 2016 Toyota Camry.\n\nThe interview comes after Homeland Security Investigations agents executed a search warrant at Omar's home on Oct. 12 as part of a reported investigation into her immigration paperwork.\n\nOmar denies wrongdoing and says the attention surrounding the investigation has left her family considering moving out of their home.\n\nDownload the FOX News app for the latest updates. https://foxnews.onelink.me/xLDS/z2jymmyl", "name": "Fox News", "handle": "FoxNews", "avatar": "https://pbs.twimg.com/profile_images/2109614018314862592/Pc5TwaVr_200x200.jpg", "likes": 855, "rts": 163, "replies": 440, "views": 267455, "ts": 1792634555, "media": [{"type": "video", "url": "https://video.twimg.com/amplify_video/2113088379822718976/vid/avc1/640x360/MAivLL4HdGcF_tIC.mp4?tag=29", "hd": "https://video.twimg.com/amplify_video/2113088379822718976/vid/avc1/1280x720/GWYzo_Arh-vGsX4r.mp4?tag=29", "thumb": "https://pbs.twimg.com/amplify_video_thumb/2113088379822718976/img/gtzle49a8kF7Pbv9.jpg", "dur": 23}], "quote": null, "reply_to": null, "cat": "AI Tools & Agents", "score": 6.97, "thread": [], "tier": "must"}, {"id": "2112955022082207978", "url": "https://x.com/markgadala/status/2112955022082207978", "text": "🚨 BREAKING: Node.js just dropped its OWN security bombshell.\n\n4 HIGH-SEVERITY vulnerabilities patched TODAY, including one that could let hackers remotely execute malicious code on vulnerable servers.\n\n→ 10 SECURITY FLAWS were addressed in today's Node.js release, FOUR rated HIGH severity.\n\n→ REMOTE CODE EXECUTION: CVE-2026-111497 is a serious flaw in Node.js's Brotli decoder that could allow attackers to execute malicious code remotely.\n\n→ TLS SECURITY BYPASS: Two separate vulnerabilities could trick affected applications into accepting certificates for the WRONG server under certain conditions.\n\n→ Think about that. Your application could establish an encrypted connection while failing to properly verify WHO it's talking to.\n\n→ THREE MAJOR NODE.JS VERSIONS AFFECTED: Node.js 22, 24 and 26 all required emergency security updates.\n\n→ RUNNING NODE.JS 18 OR 20? Those versions are END-OF-LIFE and aren't receiving these official security patches.\n\n→ PATCH IMMEDIATELY: Update to Node.js 22.23.4, 24.22.1 or 26.12.1, depending on your release line. If you're using Docker, rebuild and redeploy your containers.\n\nPHP AND Node.js both facing major security disclosures on the SAME DAY.\n\nIf you run a website or application, TODAY is the day to check your servers.\n\nAnd remember: the public release of security patches can give attackers a roadmap to systems that haven't updated.\n\nDon't be the last one to patch.", "name": "Mark Gadala-Maria", "handle": "markgadala", "avatar": "https://pbs.twimg.com/profile_images/1904279027013001216/STf4Q5To_200x200.jpg", "likes": 1985, "rts": 334, "replies": 41, "views": 299790, "ts": 1792602708, "media": [], "quote": {"id": "2112789730995933567", "url": "https://x.com/markgadala/status/2112789730995933567", "text": "🚨 A MASSIVE internet security emergency is unfolding right now. 🚨\n\nTwo CRITICAL vulnerabilities have been discovered in PHP, potentially putting millions of websites at risk.\n\n→ NEARLY 70% of websites with a known server-side language run PHP. The potential scale is ENORMOUS.\n\n→ TWO CRITICAL security flaws have been confirmed, each scoring 9.2/10 in severity.\n\n→ Attackers could potentially take control of vulnerable servers remotely, without authentication.\n\n→ Reports suggest PHP versions dating back to 2004 could be affected. The exact scope is still unconfirmed.\n\n→ EMERGENCY PATCHES are scheduled for TOMORROW at 10 AM ET. Website owners are being urged to prepare immediately.\n\n→ Europe's CERT-EU is warning organizations to patch ASAP or consider TAKING EXPOSED APPLICATIONS OFFLINE if they cannot be secured.\n\n→ WordPress, Magento, Laravel and potentially millions of other PHP-powered websites could be at risk.\n\n→ Once patches go public, hackers could reverse-engineer them and race to attack servers that haven't updated.\n\nThe vulnerabilities are CONFIRMED. The full technical details remain secret.\n\nTomorrow, the race between hackers and defenders begins.\n\nThis could get ugly. FAST.", "name": "Mark Gadala-Maria", "handle": "markgadala", "avatar": "https://pbs.twimg.com/profile_images/1904279027013001216/STf4Q5To_200x200.jpg", "likes": 4939, "rts": 781, "replies": 121, "views": 1055674, "ts": 1792563300, "media": [], "quote": null, "reply_to": null}, "reply_to": null, "cat": "Research & Safety", "score": 6.93, "thread": [], "tier": "must"}, {"id": "2112953618093535510", "url": "https://x.com/bioware/status/2112953618093535510", "text": "", "name": "BioWare", "handle": "bioware", "avatar": "https://pbs.twimg.com/profile_images/1978517038185512960/EBRNWiTK_200x200.jpg", "likes": 304544, "rts": 38843, "replies": 26645, "views": 23679595, "ts": 1792602373, "media": [{"type": "photo", "url": "https://pbs.twimg.com/media/HVKrSlSWMAArNe7.jpg?name=orig"}], "quote": null, "reply_to": null, "cat": "Everything Else", "score": 6.92, "thread": [], "tier": "must"}, {"id": "2112995138717016529", "url": "https://x.com/poteto/status/2112995138717016529", "text": "grok bot can now build Pages for you!", "name": "lauren", "handle": "poteto", "avatar": "https://pbs.twimg.com/profile_images/2093473719830315008/oo09g1Ov_200x200.jpg", "likes": 1839, "rts": 68, "replies": 161, "views": 74531, "ts": 1792612273, "media": [], "quote": {"id": "2112992872857252082", "url": "https://x.com/bot/status/2112992872857252082", "text": "Grok Bot can now build reports, memos, and dashboards.\n\nAsk Bot for a page, then edit it together or have Bot keep it up to date.", "name": "Grok Bot", "handle": "bot", "avatar": "https://pbs.twimg.com/profile_images/2087219239275069440/KW6C403V_200x200.jpg", "likes": 7003, "rts": 520, "replies": 1047, "views": 1073252, "ts": 1792611733, "media": [{"type": "video", "url": "https://video.twimg.com/amplify_video/2112992722529226752/vid/avc1/1280x720/CM_-XWr2v-MKSHHL.mp4?tag=29", "hd": "https://video.twimg.com/amplify_video/2112992722529226752/vid/avc1/1920x1080/Pj0Pze4xLpjvRJgG.mp4?tag=29", "thumb": "https://pbs.twimg.com/amplify_video_thumb/2112992722529226752/img/3vCQwgTBFW-Svcnq.jpg", "dur": 27}], "quote": null, "reply_to": null}, "reply_to": null, "cat": "AI Models & Labs", "score": 6.87, "thread": [], "tier": "must"}, {"id": "2112984667758510197", "url": "https://x.com/claudeai/status/2112984667758510197", "text": "Claude Duet draws on years of our safety and security work on agents. It never directly sees your passwords, a new classifier guards against sharing sensitive information, and the important decisions stay with you.\n\nWe’ll share more on our approach to safety in Claude Duet soon.", "name": "Claude", "handle": "claudeai", "avatar": "https://pbs.twimg.com/profile_images/1950950107937185792/QOfEjFoJ_200x200.jpg", "likes": 2064, "rts": 36, "replies": 26, "views": 406809, "ts": 1792609776, "media": [], "quote": null, "reply_to": "2112984666437546104", "cat": "AI Models & Labs", "score": 6.83, "thread": [{"id": "2112984664256241837", "url": "https://x.com/claudeai/status/2112984664256241837", "text": "We’re opening a research preview of Claude Duet, a new app where Claude works as a proactive agent.\n\nIt comes to you with what needs your attention, completes tasks you ask of it, keeps working when you step away, and checks with you before it acts on your behalf.", "name": "Claude", "handle": "claudeai", "avatar": "https://pbs.twimg.com/profile_images/1950950107937185792/QOfEjFoJ_200x200.jpg", "likes": 43210, "rts": 3270, "replies": 1714, "views": 5528053, "ts": 1792609775, "media": [{"type": "video", "url": "https://video.twimg.com/amplify_video/2112982862186106880/vid/avc1/640x360/L7zosiEUW76tqYr-.mp4?tag=29", "hd": "https://video.twimg.com/amplify_video/2112982862186106880/vid/avc1/640x360/L7zosiEUW76tqYr-.mp4?tag=29", "thumb": "https://pbs.twimg.com/media/HVLUnMDWsAAn7Pw.png", "dur": 100}], "quote": null, "reply_to": null}, {"id": "2112984666437546104", "url": "https://x.com/claudeai/status/2112984666437546104", "text": "We designed Claude Duet around Claude Opus 5.5, which gives it the judgment to decide what needs you, what can wait, and when to check with you first. It carries over the memory, skills, and connected apps from your Claude account, so there’s little to set up.", "name": "Claude", "handle": "claudeai", "avatar": "https://pbs.twimg.com/profile_images/1950950107937185792/QOfEjFoJ_200x200.jpg", "likes": 3543, "rts": 72, "replies": 52, "views": 705163, "ts": 1792609776, "media": [], "quote": null, "reply_to": "2112984664256241837"}], "tier": "must"}, {"id": "2112930776811806874", "url": "https://x.com/MatthewBerman/status/2112930776811806874", "text": "My interview with Sam Altman (@sama):\n\n0:00 Intro\n0:52 When Will AI Discover New Treatments?\n3:31 Why AI Hasn’t Killed Coding Jobs\n11:47 Personal AI Assistants\n15:39 Why Are We Busier Than Ever?\n20:10 Why the AI Consciousness Debate Worries Sam\n26:09 ChatGPT Is Too Agreeable\n30:03 OpenAI’s Bet on Chips and Cheaper Compute\n34:20 Why AI Needs a New Kind of Computer\n37:41 Sam on Pressure: “Pick the Big Thing”\n42:18 Why “AI Will Cure Cancer” Isn’t Enough", "name": "Matthew Berman", "handle": "MatthewBerman", "avatar": "https://pbs.twimg.com/profile_images/2051399921467830272/9RGo_6vv_200x200.jpg", "likes": 1650, "rts": 182, "replies": 150, "views": 176562, "ts": 1792596928, "media": [{"type": "video", "url": "https://video.twimg.com/amplify_video/2112930035783139330/vid/avc1/1280x720/gWYFthiwwWF08h-Z.mp4?tag=29", "hd": "https://video.twimg.com/amplify_video/2112930035783139330/vid/avc1/3840x2160/8zOdSj2LHhr7lcN5.mp4?tag=29", "thumb": "https://pbs.twimg.com/media/HVKjsCrbsAATbKg.jpg", "dur": 2708}], "quote": null, "reply_to": null, "cat": "AI Models & Labs", "score": 6.81, "thread": [], "tier": "must"}, {"id": "2112971597648978044", "url": "https://x.com/abdullababakre/status/2112971597648978044", "text": "defining a new category: phone-use\n\nan mcp/api that gives ai agents their own phones\n\ncloud phones. real androids. real iphones.\n\ntell your agent what to do, and it can operate a phone just like you do.\n\ntoday, ai agents face three fundamental problems and phoneuse solves them 🧵", "name": "Abdulla Ababakre", "handle": "abdullababakre", "avatar": "https://pbs.twimg.com/profile_images/2090009952249360384/FDXnxT-V_200x200.jpg", "likes": 1359, "rts": 127, "replies": 231, "views": 729947, "ts": 1792606660, "media": [{"type": "video", "url": "https://video.twimg.com/amplify_video/2112970511634567168/vid/avc1/1280x720/4th34JxyLqmEKfq5.mp4?tag=29", "hd": "https://video.twimg.com/amplify_video/2112970511634567168/vid/avc1/1920x1080/8t5XPElUmfeSyPa7.mp4?tag=29", "thumb": "https://pbs.twimg.com/amplify_video_thumb/2112970511634567168/img/WFKbCE_aJcTG4pJ5.jpg", "dur": 46}], "quote": null, "reply_to": null, "cat": "AI Tools & Agents", "score": 6.81, "thread": [], "tier": "must"}, {"id": "2112837624335409448", "url": "https://x.com/ActuFoot_/status/2112837624335409448", "text": "🚨🚨 Hansi FLICK 🇩🇪 explique la mauvaise performance du Barça, PAS À 100%, face au PSG 👇 :\n\n🗣️ « Nous avons commis TROP D’ERREURS dans ce match, notamment avec le ballon. Des pertes de balle faciles. (…)\n\nCertaines erreurs arrivent parce que les joueurs NE SONT PAS FRAIS.\n\nCe que l’équipe a dû faire ces dernières semaines est INCROYABLE. Tous les journalistes espagnols savent ce qui s’est passé après Séville. La récupération n’a pas été idéale.\n\nMais ce n’est PAS UNE EXCUSE. C’est simplement pour comprendre pourquoi nous ne sommes peut-être pas à notre meilleur niveau. »\n\n🎙️ @beinsports_FR  https://x.com/beinsports_FR/status/2112831270011240810/video/1", "name": "Actu Foot", "handle": "ActuFoot_", "avatar": "https://pbs.twimg.com/profile_images/1860995948089847808/oFkrcyD-_200x200.jpg", "likes": 2774, "rts": 109, "replies": 80, "views": 176637, "ts": 1792574718, "media": [{"type": "video", "url": "https://video.twimg.com/amplify_video/2112789484257394688/vid/avc1/1280x720/ZBI1Fqk6yywPf-bA.mp4?tag=29", "hd": "https://video.twimg.com/amplify_video/2112789484257394688/vid/avc1/1920x1080/n2uVV2g4zAsqFtLN.mp4?tag=29", "thumb": "https://pbs.twimg.com/amplify_video_thumb/2112789484257394688/img/RZZIQJTx2GmH33JL.jpg", "dur": 59}], "quote": null, "reply_to": null, "cat": "AI Video, Art & Music", "score": 6.79, "thread": [], "tier": "must"}, {"id": "2112946750264676743", "url": "https://x.com/AnthropicAI/status/2112946750264676743", "text": "Dr. Christopher Stubbs is joining our Long-Term Benefit Trust. Chris is an experimental physicist and a former Dean of Science at Harvard University. He has also advised the US government on national security and arms control.\n\nRead more: https://www.anthropic.com/news/christopher-stubbs-joins-long-term-benefit-trust", "name": "Anthropic", "handle": "AnthropicAI", "avatar": "https://pbs.twimg.com/profile_images/1798110641414443008/XP8gyBaY_200x200.jpg", "likes": 1750, "rts": 98, "replies": 126, "views": 399514, "ts": 1792600736, "media": [], "quote": null, "reply_to": null, "cat": "AI Models & Labs", "score": 6.79, "thread": [], "tier": "must"}, {"id": "2112893141992833413", "url": "https://x.com/teneo_protocol/status/2112893141992833413", "text": "If your AI product reads the live web, the page it gets depends on where the request comes from. We tested how much.\n\nAI search engines, research agents and data products all fetch live web pages to answer questions. Most of them fetch from cloud servers. Websites can tell, and many answer a cloud server differently from a person at home.\n\nThe test: we requested the homepage of the 300 most-visited websites from two places in the same minute, with identical headers. One request came from a cloud server in Paris. The other came from a home broadband connection near Dublin.\n\nWhat came back: 213 sites answered both. Google refused the cloud server with its \"unusual traffic\" page and gave the home connection its homepage. Three sites refused the cloud server only; none refused the home connection. Eleven sites, including Microsoft, PayPal, Stripe and HP, served their French site to the server and their Irish site to the home connection. Same URL, different page, and no error to tell you.\n\nSo the first question to ask any live web data provider is simple: where does the request leave the network from? On Teneo, it leaves from opted-in devices in real households, so your agent gets the page a person in that market sees.\n\nOur new guide gives you six questions to ask before you sign, the full data, and a test you can run on your own pages:\nhttps://teneo-protocol.ai/blog/live-web-data-for-ai-agents\n\nBuilding AI search, RAG or crypto data products? Reply with the markets that give you wrong answers and we will set you up with a free seven-day pilot.", "name": "Teneo Protocol", "handle": "teneo_protocol", "avatar": "https://pbs.twimg.com/profile_images/1797649020564754432/0Oav1zjU_200x200.jpg", "likes": 565, "rts": 402, "replies": 409, "views": 8524, "ts": 1792587955, "media": [{"type": "photo", "url": "https://pbs.twimg.com/media/HVKA-yzXoAA9bZD.jpg?name=orig"}], "quote": null, "reply_to": null, "cat": "AI Tools & Agents", "score": 6.77, "thread": [], "tier": "must"}, {"id": "2112951526511759861", "url": "https://x.com/SawyerMerritt/status/2112951526511759861", "text": "Morgan Stanley’s Adam Jonas in new @SpaceX note:\n\n“Getting other people to pay for your own compute infrastructure that you will ultimately use to train your own robots is a good idea. We see the neocloud build as more of a 'funding strategy' where SpaceX can exploit its comparative advantages in maximizing  intelligence-per-watt-per-$-per-second relative to peers.\n\nWe agree with Elon that the Physical Intelligence Economy (PIE) is economically multiplicative - if not by an order of mag. We believe $SPCX’s ability to help improve the rather challenging PR image of the AI/SI\ntrade is quite under-appreciated today.\n\nSpaceX is undergoing a metamorphosis largely undetected by a stock market that still views the company as a neocloud with exo-atsmospheric chops, and not a vertically-integrated, full-stack AI player.”", "name": "Sawyer Merritt", "handle": "SawyerMerritt", "avatar": "https://pbs.twimg.com/profile_images/1837744842715082752/xH9vYixL_200x200.jpg", "likes": 1379, "rts": 115, "replies": 60, "views": 98839, "ts": 1792601875, "media": [{"type": "photo", "url": "https://pbs.twimg.com/media/HVK2Nv5W4AAu6kD.jpg?name=orig"}, {"type": "photo", "url": "https://pbs.twimg.com/media/HVK2Nv9WgAAQN60.jpg?name=orig"}], "quote": null, "reply_to": null, "cat": "AI Video, Art & Music", "score": 6.7, "thread": [], "tier": "must"}, {"id": "2113011056847278486", "url": "https://x.com/elonmusk/status/2113011056847278486", "text": "People are buying FSD with a car attached, not the other way around", "name": "Elon Musk", "handle": "elonmusk", "avatar": "https://pbs.twimg.com/profile_images/2103567689515954176/aR-Kjpp4_200x200.jpg", "likes": 15471, "rts": 1305, "replies": 1282, "views": 1391893, "ts": 1792616068, "media": [], "quote": {"id": "2112998543065600047", "url": "https://x.com/SawyerMerritt/status/2112998543065600047", "text": "Tesla has just released its Q3 earnings results.\n\nHighlights:\n• EPS (non-GAAP): $0.48 (vs. $0.45 est)\n• Revenue: $28.05B (vs. $28.3B est)\n• Adjusted EBITDA: $3.90B\n• Active FSD Subscriptions: 1.74M, up 67% YoY from 1.04M\n• Net income (GAAP): $787M\n• Free cash flow: $1.53B\n• Capex: $4.73B\n• Cash & marketable securities: $45.45B, up 9% YoY", "name": "Sawyer Merritt", "handle": "SawyerMerritt", "avatar": "https://pbs.twimg.com/profile_images/1837744842715082752/xH9vYixL_200x200.jpg", "likes": 2732, "rts": 254, "replies": 130, "views": 1005041, "ts": 1792613084, "media": [{"type": "photo", "url": "https://pbs.twimg.com/media/HVLg0bgXsAAnRtf.jpg?name=orig"}], "quote": null, "reply_to": null}, "reply_to": null, "cat": "Money & Startups", "score": 6.66, "thread": [], "tier": "must"}, {"id": "2112797730829697108", "url": "https://x.com/gdb/status/2112797730829697108", "text": "towards acceleration of drug development, an extremely exciting and promising emerging application of our models", "name": "Greg Brockman", "handle": "gdb", "avatar": "https://pbs.twimg.com/profile_images/1347621377503711233/bHg3ipfD_200x200.jpg", "likes": 2033, "rts": 99, "replies": 128, "views": 82870, "ts": 1792565207, "media": [], "quote": {"id": "2112607347688583586", "url": "https://x.com/OpenAI/status/2112607347688583586", "text": "We’ve acquired Orchestra Bio, a platform that helps biopharma teams coordinate the complex process of drug development.\n\nTogether, we’ll build on Rosalind, our AI models and tools for life sciences research, to streamline those operations and help new treatments reach patients sooner.\n\nWelcome @ashokaraj_ and team!\n\nhttps://openai.com/index/openai-to-acquire-orchestra-bio/", "name": "OpenAI", "handle": "OpenAI", "avatar": "https://pbs.twimg.com/profile_images/1885410181409820672/ztsaR0JW_200x200.jpg", "likes": 7290, "rts": 681, "replies": 461, "views": 842773, "ts": 1792519816, "media": [], "quote": null, "reply_to": null}, "reply_to": null, "cat": "AI Models & Labs", "score": 6.64, "thread": [], "tier": "must"}, {"id": "2112908489198903680", "url": "https://x.com/itszn13/status/2112908489198903680", "text": "php2shell is the most consequential vulnerability I have ever helped discover. I am proud of how our team worked closely in coordination with the PHP Foundation to provide support and to harden the patch in preparation for this release.  Please read more about our approach:", "name": "itszn", "handle": "itszn13", "avatar": "https://pbs.twimg.com/profile_images/1480639802978422788/Jt0ku86C_200x200.jpg", "likes": 1319, "rts": 146, "replies": 44, "views": 97739, "ts": 1792591614, "media": [{"type": "photo", "url": "https://pbs.twimg.com/media/HVKPEM4bEAADKl5.jpg?name=orig"}, {"type": "photo", "url": "https://pbs.twimg.com/media/HVKPEMnaAAA3BWb.jpg?name=orig"}], "quote": {"id": "2112907856018309586", "url": "https://x.com/OpenAI/status/2112907856018309586", "text": "OpenAI models helped researchers—operating as part of our Patch the Planet initiative—discover critical security flaws in PHP, an open-source programming language used to run an estimated 70% of websites.\n\nOver the past two months, we led a coalition of maintainers, researchers, and security providers to prepare fixes and protections ahead of disclosure. This duration was necessary because the fix was quite intricate and required a major change to the PHP engine. Every site using PHP can now safely upgrade their version to stay secure, in addition to applying mitigations from various security vendors.\n\nDue to the severity of these flaws and PHP’s widespread use, we consider this bug to be one of the most impactful vulnerabilities in recent memory. It also marks a new phase, where AI can find security bugs with internet-scale impact. \n\nThis is an example of the Defender’s Window in action: to our knowledge, frontier AI was able to find this vulnerability ahead of attackers, giving defenders time to prepare.\nhttps://openai.com/index/coordinated-disclosure-of-critical-vulnerabilities/", "name": "OpenAI", "handle": "OpenAI", "avatar": "https://pbs.twimg.com/profile_images/1885410181409820672/ztsaR0JW_200x200.jpg", "likes": 13815, "rts": 2762, "replies": 541, "views": 5062111, "ts": 1792591463, "media": [], "quote": null, "reply_to": null}, "reply_to": null, "cat": "AI Models & Labs", "score": 6.64, "thread": [], "tier": "must"}, {"id": "2112987404361699535", "url": "https://x.com/Da7_Tech/status/2112987404361699535", "text": "Anthropic is going all out.\n\nWithout a doubt, this will be the real competitor to Grok Bot.", "name": "Da7em", "handle": "Da7_Tech", "avatar": "https://pbs.twimg.com/profile_images/2029551499177598976/N9ld_4ZS_200x200.jpg", "likes": 1210, "rts": 24, "replies": 45, "views": 147815, "ts": 1792610429, "media": [], "quote": {"id": "2112984664256241837", "url": "https://x.com/claudeai/status/2112984664256241837", "text": "We’re opening a research preview of Claude Duet, a new app where Claude works as a proactive agent.\n\nIt comes to you with what needs your attention, completes tasks you ask of it, keeps working when you step away, and checks with you before it acts on your behalf.", "name": "Claude", "handle": "claudeai", "avatar": "https://pbs.twimg.com/profile_images/1950950107937185792/QOfEjFoJ_200x200.jpg", "likes": 43204, "rts": 3270, "replies": 1714, "views": 5522623, "ts": 1792609775, "media": [{"type": "video", "url": "https://video.twimg.com/amplify_video/2112982862186106880/vid/avc1/640x360/L7zosiEUW76tqYr-.mp4?tag=29", "hd": "https://video.twimg.com/amplify_video/2112982862186106880/vid/avc1/640x360/L7zosiEUW76tqYr-.mp4?tag=29", "thumb": "https://pbs.twimg.com/media/HVLUnMDWsAAn7Pw.png", "dur": 100}], "quote": null, "reply_to": null}, "reply_to": null, "cat": "AI Models & Labs", "score": 6.63, "thread": [], "tier": "must"}, {"id": "2112931457786081428", "url": "https://x.com/elonmusk/status/2112931457786081428", "text": "Some fools still think the legacy news is real. Amazing.", "name": "Elon Musk", "handle": "elonmusk", "avatar": "https://pbs.twimg.com/profile_images/2103567689515954176/aR-Kjpp4_200x200.jpg", "likes": 179534, "rts": 22276, "replies": 8100, "views": 9262500, "ts": 1792597090, "media": [], "quote": null, "reply_to": null, "cat": "Everything Else", "score": 6.63, "thread": [], "tier": "must"}, {"id": "2112801229508383074", "url": "https://x.com/BrianRoemmele/status/2112801229508383074", "text": "New X Money Grok Bot!\n\nFew understand how powerful it is to have Grok Bot understand your finances and your financial goals.\n\nThe X Money MCP connection to Grok Bot is just the beginning of where this will go.\n\nThe power to see connections you may not see to long horizon goals is just one Grok Bot away.\n\nYou are living in the future with how powerful this Bot is.\n\nReports like you never seen in any bank statement.\n\nGive it a try", "name": "Brian Roemmele", "handle": "BrianRoemmele", "avatar": "https://pbs.twimg.com/profile_images/1492616506/Brian-Med-Green-Fin_200x200.png", "likes": 1541, "rts": 156, "replies": 131, "views": 443337, "ts": 1792566041, "media": [{"type": "photo", "url": "https://pbs.twimg.com/media/HVIthU4bIAAawIl.jpg?name=orig"}], "quote": {"id": "2112763030648062096", "url": "https://x.com/BrianRoemmele/status/2112763030648062096", "text": "ONLY GROK BOT DOES THIS!\n\nX MONEY + GROK BOT = WOW!\n\nEvery Monday morning your Grok Bot reads your X Money account and gives you a deep weekly report 💸\n\nGet in now: https://x.ai/bot/cMpw0zb2v9RRtQPDfsVFm\n\n- Balances across every account, with the week's net change\n\n- Every transaction sorted into categories automatically\n\n- Top spending categories, week-over-week trends, and my biggest charges\n\n- Cash-back and interest earned, tracked as they add up\n\n- Recurring subscriptions flagged so nothing slips by\n\n- Three habit tips drawn from my actual numbers\n\n- Progress rings for my savings rate, monthly investing, and spending cap\n\nINVEST: Then it asks me about my goals: am I on track, do I want to change a target, and should it set up automatic investing in Coinbase? It prepares the buy, I tap Approve, and only then is the order placed.\n\nIt all comes as a dark-mode dashboard with charts, plus a PDF.\n\nThe bot only reads my account by default. No money moves and no trade is placed without my Approve, every time.\n\nTry it out, you will never go back to boring credit card statements: https://x.ai/bot/cMpw0zb2v9RRtQPDfsVFm\n\nHere's a sample report (example data) 👇", "name": "Brian Roemmele", "handle": "BrianRoemmele", "avatar": "https://pbs.twimg.com/profile_images/1492616506/Brian-Med-Green-Fin_200x200.png", "likes": 209, "rts": 20, "replies": 37, "views": 458424, "ts": 1792556934, "media": [{"type": "photo", "url": "https://pbs.twimg.com/media/HVIJX1AaAAAgufb.jpg?name=orig"}, {"type": "photo", "url": "https://pbs.twimg.com/media/HVIJaInbYAAcP-3.jpg?name=orig"}, {"type": "photo", "url": "https://pbs.twimg.com/media/HVIJby2boAA-EQq.jpg?name=orig"}, {"type": "photo", "url": "https://pbs.twimg.com/media/HVIJddbbkAAl2bp.jpg?name=orig"}], "quote": null, "reply_to": null}, "reply_to": null, "cat": "AI Models & Labs", "score": 6.59, "thread": [], "tier": "must"}, {"id": "2112898237699068338", "url": "https://x.com/DAIEvolutionHub/status/2112898237699068338", "text": "Google just dropped a 1-hour course on agentic engineering from scratch:  \n\n00:00 – How to build your first AI agent \n08:24 – Build agent memory (short, persistent, long) \n28:34 – Agentic loops, long-running AI agents \n40:04 – How to build MCP (MCP vs API) \n1:00:22 – Multi-agentic systems  \n\nThis 1-hour watch will replace 10 paid agentic courses on the internet.  \n\nBookmark this. Watch this weekend.", "name": "Kshitij Mishra | AI & Tech", "handle": "DAIEvolutionHub", "avatar": "https://pbs.twimg.com/profile_images/2015092541159280641/941zc6PA_200x200.jpg", "likes": 948, "rts": 218, "replies": 21, "views": 46899, "ts": 1792589170, "media": [{"type": "video", "url": "https://video.twimg.com/amplify_video/2112897715457933312/vid/avc1/640x360/FmGWYZJZw9mpxYP7.mp4?tag=29", "hd": "https://video.twimg.com/amplify_video/2112897715457933312/vid/avc1/1280x720/7UW-sXSNwEuQBuVg.mp4?tag=29", "thumb": "https://pbs.twimg.com/amplify_video_thumb/2112897715457933312/img/vuIoyI82zcS5t-xt.jpg", "dur": 4335}], "quote": null, "reply_to": null, "cat": "AI Tools & Agents", "score": 6.58, "thread": [], "tier": "must"}, {"id": "2112945705757315307", "url": "https://x.com/sundarpichai/status/2112945705757315307", "text": "Great to sit down with @alexeheath to talk about Argon, the frontier, and our plans for personal agents!", "name": "Sundar Pichai", "handle": "sundarpichai", "avatar": "https://pbs.twimg.com/profile_images/2051799620062429184/AL8CoAUG_200x200.jpg", "likes": 910, "rts": 76, "replies": 103, "views": 100875, "ts": 1792600487, "media": [], "quote": {"id": "2112937498305564789", "url": "https://x.com/alexeheath/status/2112937498305564789", "text": "Sundar Pichai on Gemini 4 and the AI compute crunch\n\nEven Google can’t get enough compute. I sit down with Google and Alphabet CEO @sundarpichai shortly after the wider release of Gemini 4 Argon to discuss its early reception, where he still wants the model to improve, and what it takes to keep Google at the frontier of AI.\n\nPichai explains the recent leadership shakeup at Google DeepMind and why building frontier models has become an “all-consuming” job. We also get into Google’s answer to the personal agent race, how he predicts Gemini will do more work on your behalf, and whether agents will finally bring Search, Gmail, and Gemini together.\n\nI ask him about Google turning free cash flow negative, the risks in the AI infrastructure buildout, and how he plans for demand years before knowing what the models will be capable of. He explains the signals giving him confidence to keep spending and how he uses AI agents to follow model development and compute usage inside Google.\n\nTimestamps:\n00:00 Gemini Argon launch reception\n01:49 Model access and safety\n06:20 The AI model race\n08:35 Agentic breakthroughs and 2027\n11:34 Recursive self-improvement\n15:41 DeepMind leadership changes\n19:52 Google's AI compute investments\n25:20 Is AI spending sustainable?\n33:18 How Sundar uses AI agents\n35:35 Gemini's personal agent plans\n38:37 How AI agents change the web\n43:52 Google's space data centers\n47:38 Waymo's expansion strategy\n50:26 Wing's drone delivery plans\n51:36 AI safety and regulation\n55:58 Google's quantum computing bet\n\nYouTube: https://youtu.be/fJBSNEFdm8c\nSpotify: https://open.spotify.com/episode/0cJBqmVz3CWJSPdmBOeJGu?si=NBxJIMhZRgikafPtwY0sZA\nSubstack: https://sources.news/p/sundar-pichai-gemini-4-google-other-bets\nApple Podcasts: https://podcasts.apple.com/us/podcast/sundar-pichai-on-gemini-4-and-the-ai-compute-crunch/id1840154537?i=1000797461022\n\nThis episode's presenting sponsor is @hyperagentapp. Thanks to the show’s premiere sponsors: @Atlassian, @meetgranola, and @mercury.", "name": "Alex Heath", "handle": "alexeheath", "avatar": "https://pbs.twimg.com/profile_images/1983378648787988480/cGjEMRvw_200x200.jpg", "likes": 129, "rts": 14, "replies": 15, "views": 107226, "ts": 1792598530, "media": [{"type": "video", "url": "https://video.twimg.com/amplify_video/2112933601084129280/vid/avc1/1280x720/1w0RbfzRpcMz5oWK.mp4?tag=29", "hd": "https://video.twimg.com/amplify_video/2112933601084129280/vid/avc1/3840x2160/F8UBcOSxMlJlHgCG.mp4?tag=29", "thumb": "https://pbs.twimg.com/amplify_video_thumb/2112933601084129280/img/w6nQGBH2G9Q2UoBY.jpg", "dur": 3549}], "quote": null, "reply_to": null}, "reply_to": null, "cat": "AI Models & Labs", "score": 6.56, "thread": [], "tier": "must"}, {"id": "2113002610806730780", "url": "https://x.com/lydiahallie/status/2113002610806730780", "text": "Claude Duet has made focused work so much easier! Not having to be \"on\" all the time is so nice, way less context switching\n\nMy setup is boring lol but I have it watch Slack/email/cal and only ping me when it matters (even threads I'm not in), often with a doc/design for context!", "name": "Lydia Hallie ✨", "handle": "lydiahallie", "avatar": "https://pbs.twimg.com/profile_images/1994238936345137154/exEBW2UI_200x200.jpg", "likes": 857, "rts": 28, "replies": 89, "views": 35018, "ts": 1792614054, "media": [], "quote": {"id": "2112984664256241837", "url": "https://x.com/claudeai/status/2112984664256241837", "text": "We’re opening a research preview of Claude Duet, a new app where Claude works as a proactive agent.\n\nIt comes to you with what needs your attention, completes tasks you ask of it, keeps working when you step away, and checks with you before it acts on your behalf.", "name": "Claude", "handle": "claudeai", "avatar": "https://pbs.twimg.com/profile_images/1950950107937185792/QOfEjFoJ_200x200.jpg", "likes": 43193, "rts": 3269, "replies": 1713, "views": 5522623, "ts": 1792609775, "media": [{"type": "video", "url": "https://video.twimg.com/amplify_video/2112982862186106880/vid/avc1/640x360/L7zosiEUW76tqYr-.mp4?tag=29", "hd": "https://video.twimg.com/amplify_video/2112982862186106880/vid/avc1/640x360/L7zosiEUW76tqYr-.mp4?tag=29", "thumb": "https://pbs.twimg.com/media/HVLUnMDWsAAn7Pw.png", "dur": 100}], "quote": null, "reply_to": null}, "reply_to": null, "cat": "AI Models & Labs", "score": 6.56, "thread": [], "tier": "must"}, {"id": "2112922760083071204", "url": "https://x.com/googlemaps/status/2112922760083071204", "text": "Gemini is coming to Google Maps navigation on CarPlay, bringing you a helpful, conversational assistant right to your in-car display. Try asking things like:\n\n🚗 “What park is famous for gorgeous views overlooking the city?”\n🌤️ “I want to go at a time when it’s not too busy and the weather will stay nice. Is now a good time?”\n🧭 “Start navigating me there but make sure to avoid toll roads.”\n\nRolling out now everywhere Gemini is available — just tap the Gemini icon in Google Maps on your car’s display to try it on your next drive.", "name": "Google Maps", "handle": "googlemaps", "avatar": "https://pbs.twimg.com/profile_images/2028882435585249280/pENAnNHz_200x200.jpg", "likes": 1060, "rts": 92, "replies": 47, "views": 77964, "ts": 1792595016, "media": [{"type": "video", "url": "https://video.twimg.com/amplify_video/2112922694387712002/vid/avc1/720x720/BQ_N41NE-YaRuod3.mp4?tag=29", "hd": "https://video.twimg.com/amplify_video/2112922694387712002/vid/avc1/1080x1080/nDmxGHm_-iKh6uFf.mp4?tag=29", "thumb": "https://pbs.twimg.com/amplify_video_thumb/2112922694387712002/img/0l__If4oBay3LZkq.jpg", "dur": 40}], "quote": null, "reply_to": null, "cat": "AI Models & Labs", "score": 6.55, "thread": [], "tier": "must"}, {"id": "2112980072240238723", "url": "https://x.com/EHuanglu/status/2112980072240238723", "text": "I make it look better", "name": "el.cine", "handle": "EHuanglu", "avatar": "https://pbs.twimg.com/profile_images/1793460098867838976/hoeoWt9M_200x200.jpg", "likes": 829, "rts": 63, "replies": 85, "views": 52523, "ts": 1792608681, "media": [{"type": "video", "url": "https://video.twimg.com/amplify_video/2112980015885512704/vid/avc1/1280x720/cwQtfAgHIjxW6JDe.mp4?tag=29", "hd": "https://video.twimg.com/amplify_video/2112980015885512704/vid/avc1/1920x1080/zujL3EUT_HKAbeSS.mp4?tag=29", "thumb": "https://pbs.twimg.com/amplify_video_thumb/2112980015885512704/img/ZWO4mUbxoKeYbPa3.jpg", "dur": 29}], "quote": {"id": "2112819774573179175", "url": "https://x.com/UnitreeRobotics/status/2112819774573179175", "text": "Unitree Introducing: H2-X Kung Fu Legend Guardian🤖\nPowerful performance to serve and guard you, with a maximum endurance of approximately 8 hours.\nPlease use the robot safely and in a friendly manner.", "name": "Unitree", "handle": "UnitreeRobotics", "avatar": "https://pbs.twimg.com/profile_images/1844926705389142016/nIEbH8rV_200x200.jpg", "likes": 20508, "rts": 2766, "replies": 1427, "views": 4242473, "ts": 1792570463, "media": [{"type": "video", "url": "https://video.twimg.com/amplify_video/2112814220194828288/vid/avc1/1280x720/qQFeTMrcQITPE76L.mp4?tag=29", "hd": "https://video.twimg.com/amplify_video/2112814220194828288/vid/avc1/1920x1080/dphHVlNFst1G9RW0.mp4?tag=29", "thumb": "https://pbs.twimg.com/amplify_video_thumb/2112814220194828288/img/RL8lXu0dfq4qop9M.jpg", "dur": 61}], "quote": null, "reply_to": null}, "reply_to": null, "cat": "AI Tools & Agents", "score": 6.55, "thread": [], "tier": "must"}, {"id": "2113033492317487312", "url": "https://x.com/synthwavedd/status/2113033492317487312", "text": "It took Railway almost 15 hours to notify its thousands of customers that their environmental variables have been compromised. Several people on this app raised alarm about their keys being drained and/or receiving \"your key has been compromised\" emails\n\nSuper irresponsible", "name": "leo 🐾", "handle": "synthwavedd", "avatar": "https://pbs.twimg.com/profile_images/2070520587659657216/novnWEZQ_200x200.jpg", "likes": 817, "rts": 22, "replies": 26, "views": 33574, "ts": 1792621417, "media": [{"type": "photo", "url": "https://pbs.twimg.com/media/HVMAB_cXUAATcWS.jpg?name=orig"}], "quote": {"id": "2113025284148715845", "url": "https://x.com/Railway/status/2113025284148715845", "text": "An urgent notice from the Railway team\n\nhttps://blog.railway.com/p/security-disclosure-wednesday-october-21st", "name": "Railway", "handle": "Railway", "avatar": "https://pbs.twimg.com/profile_images/2060407291996692484/ave6xJl9_200x200.jpg", "likes": 4205, "rts": 725, "replies": 452, "views": 1905708, "ts": 1792619460, "media": [], "quote": null, "reply_to": null}, "reply_to": null, "cat": "AI Tools & Agents", "score": 6.52, "thread": [], "tier": "must"}, {"id": "2113021211282141469", "url": "https://x.com/DaveShapi/status/2113021211282141469", "text": "I've deleted my Grok Bot again. I tried. I really, really, really tried. \n\nHere's my observation:\n\n1) Grok repeatedly chooses the dumbest way to do things. You have to spoon feed it and hold its hand on basic tasks that no other AI struggles with. Down to the point that you have to micro manage it. Unacceptable. \n\n2) Grok has zero consideration for user time. It does things in serial, doesn't check, and you have to constantly check on it like \"hey buddy, where is this work?\" and it's like \"Uhh... oh yeah that process hung...\" it's like working with your brother's stoner friend. \n\n3) Grok utterly refuses to discuss which model is backing it. It's got very Woke Right vibes like \"you just have to trust me bro\" like no, I'm paying for a service, if you're not going to be transparent, I don't care. It's one thing if that model is instructed to be opaque (which is idiotic to start with), but there's no dashboard to see what model you're using. \n\nGrok remains the most disappointing model out there. Full stop.", "name": "David Shapiro (L/0)", "handle": "DaveShapi", "avatar": "https://pbs.twimg.com/profile_images/2038311372656709632/0l2NmU5T_200x200.jpg", "likes": 384, "rts": 8, "replies": 270, "views": 57202, "ts": 1792618489, "media": [], "quote": null, "reply_to": null, "cat": "AI Models & Labs", "score": 6.51, "thread": [], "tier": "must"}, {"id": "2112925384324870620", "url": "https://x.com/itsolelehmann/status/2112925384324870620", "text": "global crime rates are gonna collapse once superhumanoids like this hit the streets\n\nimagine facing this thing as a robber lol\n\nUnitree’s new \"Guardian\" robot can fight off a guy with a knife and patrol areas for 8 hours straight\n\nwhich is terrible news for criminals, because the biggest thing that stops them from committing crimes is the chance of getting caught\n\nright now in the US only about 13% of burglaries ever get solved\n\nso most burglars are making a pretty safe bet\n\nbut if you put a robot on every block that:\n\n> never sleeps\n> records everything\n> and can physically stop/beat the shit out of you\n\n...then almost no criminals would make that bet anymore\n\non top of that, if you add the abundance that AI and robotics are likely to create\n\nthen far fewer people will even get desperate enough to commit crimes in the first place, because they'll already have enough\n\nthere's a good chance that our kids will think about robbery the way we think about guillotine executions https://x.com/CyberRobooo/status/2112829207927746974/video/1", "name": "Ole Lehmann", "handle": "itsolelehmann", "avatar": "https://pbs.twimg.com/profile_images/1633697720291704832/GBmxTCa6_200x200.jpg", "likes": 582, "rts": 60, "replies": 245, "views": 70675, "ts": 1792595642, "media": [{"type": "video", "url": "https://video.twimg.com/amplify_video/2112829112951980032/vid/avc1/1280x720/tvIYmp-Z0M7IEFKX.mp4?tag=29", "hd": "https://video.twimg.com/amplify_video/2112829112951980032/vid/avc1/1920x1080/G5_aLQrsRztsybz2.mp4?tag=29", "thumb": "https://pbs.twimg.com/amplify_video_thumb/2112829112951980032/img/w3Kr77s-IApo95SP.jpg", "dur": 20}], "quote": null, "reply_to": null, "cat": "AI Video, Art & Music", "score": 6.5, "thread": [], "tier": "must"}, {"id": "2112901360555577409", "url": "https://x.com/petergostev/status/2112901360555577409", "text": "I hope you've asked the doctors if they are ok with you healing diseases", "name": "Peter Gostev", "handle": "petergostev", "avatar": "https://pbs.twimg.com/profile_images/1934694573797670912/1gnGJwlr_200x200.jpg", "likes": 1139, "rts": 47, "replies": 25, "views": 21233, "ts": 1792589914, "media": [], "quote": {"id": "2112899854569762936", "url": "https://x.com/OpenAI/status/2112899854569762936", "text": "GPT-Rosalind surfaced a new lead for drug discovery: could restoring cholesterol transport protect neurons from degeneration?\n\nDCTN1 is a gene linked to Perry syndrome, a rare neurodegenerative disorder. In mouse-brain data, disrupting it increased expression of genes involved in making cholesterol. GPT-Rosalind suggested a possible explanation: cholesterol may not be reaching where neurons need it.\n\nThat gives scientists a specific mechanism to test and, if confirmed, a direction for developing new treatments for neurodegenerative disorders.\n\nWith @perturbai_tx and @scrippsresearch, a team of thousands of GPT-Rosalind agents worked in parallel, connecting gene-expression results from millions of mouse brain cells with scientific literature in just 32 minutes. We’re now expanding this collaboration to identify new drug targets.\n\nhttps://openai.com/index/scaling-ai-research-for-complex-biological-data/", "name": "OpenAI", "handle": "OpenAI", "avatar": "https://pbs.twimg.com/profile_images/1885410181409820672/ztsaR0JW_200x200.jpg", "likes": 6098, "rts": 625, "replies": 354, "views": 1121496, "ts": 1792589555, "media": [], "quote": null, "reply_to": null}, "reply_to": null, "cat": "AI Models & Labs", "score": 6.49, "thread": [], "tier": "must"}, {"id": "2112787432282190218", "url": "https://x.com/CognyAI/status/2112787432282190218", "text": "Since yesterday:\n\nCross-chat memory is now on every plan. What Cogny learns in one chat carries into the next.\n\nThe live voice agent can now make motion design ads, not just AI video.\n\nMore coming. https://cogny.com", "name": "Cogny", "handle": "CognyAI", "avatar": "https://pbs.twimg.com/profile_images/2049529841926426624/0OQ56ndN_200x200.png", "likes": 1492, "rts": 83, "replies": 59, "views": 35535, "ts": 1792562752, "media": [{"type": "video", "url": "https://video.twimg.com/ext_tw_video/2112787386090266624/pu/vid/avc1/480x600/7gQrpfJnJyL65uG9.mp4?tag=12", "hd": "https://video.twimg.com/ext_tw_video/2112787386090266624/pu/vid/avc1/720x900/_ZgB5pgPZZ8LcFe_.mp4?tag=12", "thumb": "https://pbs.twimg.com/ext_tw_video_thumb/2112787386090266624/pu/img/YL0WyO_zUJflx4RE.jpg", "dur": 14}], "quote": null, "reply_to": null, "cat": "AI Tools & Agents", "score": 6.48, "thread": [], "tier": "must"}, {"id": "2112872463172325377", "url": "https://x.com/WatcherGuru/status/2112872463172325377", "text": "JUST IN: 🇺🇸 US officially finalizes new crypto stablecoin regulations under the GENIUS Act.", "name": "Watcher.Guru", "handle": "WatcherGuru", "avatar": "https://pbs.twimg.com/profile_images/1641221212578754562/DfiC0KW2_200x200.png", "likes": 14844, "rts": 1917, "replies": 419, "views": 1338323, "ts": 1792583025, "media": [], "quote": null, "reply_to": null, "cat": "Money & Startups", "score": 6.46, "thread": [], "tier": "must"}]);